mapper.select:
SELECT USER_EMAIL, TITLE, CONTENT, BOARD_NUM
FROM PLANT_STORY
ORDER BY REG_DATE DESC;

SELECT USER_EMAIL, TITLE, REG_DATE, READ_CNT, CONTENT
FROM PLANT_STORY
WHERE BOARD_NUM = #{boardNum}

mapper.update:
UPDATE PLANT_STORY
SET READ_CNT = READ_CNT + 1
WHERE BOARD_NUM = #{boardNum};

UPDATE PLANT_STORY
SET TITLE = #{title}, CONTENT = #{content}
WHERE BOARD_NUM = #{boardNum}
